from pathlib import Path
R=Path('/workspace/scratch/1544cec576c6');D=R/'ud-public/dist'
C=R/'ud-repo/captures/2026-10-20T180500Z-codex-clock-plant-c4d128b7'
names=['UD_CLOCK_PLANT_COMPATIBILITY_v0.1.pdf','UD_CLOCK_PLANT_COMPATIBILITY_v0.1.tex','clock_plant_certificate.py','sampled_actuator_dependency.py','finite_record_dependency.py','CLOCK_PLANT_CERTIFICATE_v0.1.json','INHERITED_BUDGET_REPLAY_v0.1.json','MANUFACTURER_AUDIT_v0.1.json','IDENTIFICATION_PLAN_v0.1.json','PROVENANCE_v0.1.json','PDF_QA_v0.1.json','requirements.txt']
